    "email": "malinxi321@126.com;3209554852@qq.com;1071507994@qq.com;matingmolly@126.com;962363279@qq.com;zhang.xueying@toread.com;zhu.mantang@toread.com.cn;ir300005@toread.com.cn",
    "companyType": "",
