    "profile": "江西南美伊服饰有限公司成立于 2012 年，是一家集设计、生产、 销售于一体的团体服装方案供应企业，致力于为安全生产、应急救援、 公共基础建设、医院院校等企业单位提供 PPE 服装一站式解决方案。总部位于江西宜春市奉新县高新技术园区。拥有自动化针、梭织服装生产线十五条、（包含德国拓卡奔马全自动裁床、意大利迈卡自动贴袋、开袋、钉扣、锁眼、袖叉机及意大利威比玛全自动裤袢机、全自动接橡筋、激光模版机、激光切割机等系列自动化设备，生产线工人300 余人。南美伊立足江西、服务全球，在南昌、北京、上海、广州、金华均设有子公司或办事处。本公司拥有完整成熟的跨境电子商务 B2B、B2C 团队及新媒体运营团队，获得 20 多个国家专业卖家的认可。有大洋洲的澳大利亚、巴布亚新几内亚、新西兰、斐济;美洲的美国、加拿大 、墨西哥、巴拿马;欧洲的意大利、德国、爱尔兰、丹麦、芬兰、葡萄牙、 法国、荷兰、希腊、马耳他、爱沙尼亚、瑞典、 挪威;亚洲的阿拉伯酋长国、泰国、阿曼、沙特阿拉伯、马来西亚、新加坡、以色列;非洲的卢旺达，埃及，刚果金。公司正在进一步加强标准化、精细化生产管理建设工作，进一步提升产品质量的稳定性及竞争力。公司已陆续通过欧盟 BSCI 国际认证、 法国 EV 国际认证;获得多项实用新型专利，通过 ISO 三大体系认证、 五星级售后服务认证;并于 2020 年获得国家技术企业、科技型中小企业认证、荣获 2021 年江西省“专精特新”中小企业。",
