    "profile": "杭州布鲁科乐服装有限公司是一家集开发、设计、生产、经营于一体，服务对象遍及全国的现代化职业服装专业企业。公司前身杭州蓝领服装有限公司因经营方向发生转变，不再涉及服装类业务，蓝领公司原经营团队为继续经营服装业务，于2019年9月新成立了杭州布鲁科乐服装有限公司，完全承接原杭州蓝领服装有限公司的经营场地、生产设备、技术力量、品牌商标及生产管理原班人员，延续蓝领品牌的经营理念与企业文化，并新增服装网络销售业务与平面广告业务。　　公司已通过ISO9001国际质量体系认证，原蓝领公司是国家电力公司全国电力系统职业服装生产推荐企业，是浙江省劳动厅定点生产单位，连续数年被评为杭州市“重合同守信用”单位和浙江省“服务质量信得过”单位。产品已被国内各大发电集团、电网企业、大型工矿企业及全国数十个省、市、地区千余家单位作为指定产品，广泛使用。　　我公司现有厂区场地6000余平方米，员工200余人。拥有专业的CAD服装设计中心、样版制作中心、制服展示中心和生产车间，并有销售（客服）部为您提供一流的售前和售后服务，平均年产服装50余万套（件）。　　“保证产品质量，维护企业信誉，做好优质服务，坚持用户至上”是本公司的一贯宗旨；“集职业服装技术之精，创职业服装产品之优”、为全国各行业职工“上班保一生平安，下班展一身风采”是我们的忠心愿望；为各单位的企业形象增光添彩是我们的奋斗目标。在今后的发展道路中，公司将不断通过管理创新、产品创新、营销创新，增强自身的竞争力，以优质的产品和优良的服务竭诚回报用户。　　会天下友，制四海衣。蓝领服装，致力缔造中国卓越品牌，回报和奉献社会各界客户，为您带来碧海蓝天的工作心情，和您携手引领职场新潮流。",
