    "profile": "浙江蓝天鹤舞控股有限公司创立于1988年，是一家集研发、设计、生产职业装(工作服)于一体的成熟型品牌公司，总注册资本1.16亿元，在浙江杭州和四川广元都有生产基地，总占地面积350亩，拥有员工1000余人，年产工作服300万件。蓝天鹤舞秉承“立足主业、延伸发展”的战略构想，形成了多维度延伸发展的成熟型经济体，公司创建蓝天鹤舞商务科技室，成功研发智能工装，并取得国家专利，成为国内较早掌握该核心技术的职业装企业。不断拓展生产规模，先后投产萧山经济技术开发区、广元()川浙经济开发区，成为同类企业中的佼佼者。蓝天鹤舞秉承“精益求精、追求”的品牌建设理念。“鹤舞”商标先后被评为杭州市、浙江省、浙江省产品、全国用户质量满意信得过品牌，同时也是国内职业装行业较早获得“驰名商标”的企业。坚持人性化的创新设计、现代化的质量管控和诚信品牌运作，蓝天鹤舞正式成为职业装发展的带领者。蓝天鹤舞秉承“客户至上、诚信为本”的合作态度，以其经典上乘的品质和服务得到政府的认同，成为建国60典服装和国家体育总局定点生产企业，是政府采购理想品牌。圆满完成北京奥运会社会志愿者、社会治安志愿者服装、“神七”酒泉发射基地人员服装和上海世博会安保服装的设计、生产任务。此外，蓝天鹤舞与国内外大型企业保持长期合作关系，有石油、石化、国家电网、邮政、航空工业、船舶、中钢集团、上海大众集团、奥的斯集团、娃哈哈集团、万向集团、SEAN JHON(美国)、ELIS(法国)、BEROEPSKLEDINGB.V.(俄罗斯)和WOOLWORTH(南非)等，公司在全国建立了五大区域销售管理处和各级代理商，为客户提供24小时的服务保障。依托成熟的技术力量、深厚的文化底蕴、严谨的生产工艺、规范的制度管理、完善的售后服务，“鹤舞”产品得到了国内外用户的一致好评。",
    "businessScope": "一般项目：第一类医疗器械生产；医护人员防护用品生产（Ⅰ类医疗器械）；医护人员防护用品批发；医护人员防护用品零售；第一类医疗器械销售；第二类医疗器械销售；服装研发、设计；生产：服装，皮革制品,，羊毛衫，床上用品，劳保防护用品，化纤布；销售：橡胶制品、塑料制品、日用百货、雨衣雨靴、鞋类及头部防护用品；货物及技术的进出口**（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：医护人员防护用品生产（Ⅱ类医疗器械）；医用口罩生产；第二类医疗器械生产；第二类增值电信业务（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）。"
