    "profile": "专业研发、设计、生产、销售、服务，专注安全、舒适、健康、品味、时尚。江苏成龙服饰科技有限公司始建于1996年，地处无锡市锡山区，相邻于苏州、张家港、江阴。公司以长江三角纺织织产品资源与技术为优势，早在2005年公司实行“产业拓展与产能扩张”战略，组建了安徽成龙泰尼服饰有限公司、江苏恒泰易通科技有限公司，并以销售控股30X投资合作模式，拥有江苏盾王劳保用品有限公司、江苏狮龙共舞服饰有限公司为合资合作控股企业。公司主要生产商务行政装、职业制服、职业工装、特种防护服、户外旅行服、高寒防寒服等系列产品，以及多功能防护鞋等防护用品。目前拥有员工900名，年生产各类产品70余万套，公司设有4个业务营销部和在国内设有包括北京在内的15个业务机构。主要业务涉及电力电建、交通电信、烟草与物流、矿产冶金、中国石油石化、中国航空航天、中国兵器工业、化工制药、等行业企事业和公共事业单位。公司确立以产学研和自主知识权创新为发展导向，以传统产业向科技转型，在不断完善企业单位员工素质化、管理现代化、产业规模化、市场行业化的同时，坚定树立“不止满足市场需求，更是引导行业进步”市场发展理念，注重市场调研与产品研发注重产业科技投入，战略性实施专业院校与专业科研机构的科技合作。荣获江苏省民营科技型企业、江苏省技术企业、江苏省产品质量标准生产示范企业、获批并成立无锡市安全防护工程研究所。已获发明、新颖、外观各项专利共计40余项。同时公司还先后获得国家安监总局安标颁发的安全标志证书、1S09001：2015国际质景体系认证证书、1S014001：2015环境管理体系认证证书、GB/T45001-2020职业健康安全管理体系认证证书、国内售后服务五星认证……。成龙人知道，以高素质技术人才、高精尖技术设备、高品质原辅材料、高灵敏市场需求去完成和实现安全、舒适、健康、品味、时尚的产品。成龙人明白，质量源于意识，效益源于管理，市场源于专业，信誉源于诚信。每一份订单都是对我们每一项工作的勘验，每一环节都是对我们每一项素质的测试。成龙人坚信，客户的口碑比一切都重要。",
    "businessScope": "服装、服装面辅料、纺织品、针织品、一般劳动防护用品、特种劳动防护用品、防静电服、阻燃服、酸碱类化学品防护服、防电弧服、高压静电防护服、带电作业屏蔽服、羽绒服、校服、西装、T恤、衬衫、内衣、毛衣、冲锋衣、领带、帽、手套、袜子、绝缘鞋、安全鞋、皮鞋、雨靴、雨衣、皮革制品、箱包、皮带的研发、生产、销售；服装服饰设计；企业形象策划；安全工器具、五金产品、日用品、办公用品、文化用品、床上用品、体育用品及器材的销售；自营和代理各类商品及技术的进出口业务，但国家限定企业经营或禁止进出口的商品及技术除外。医护人员防护用品生产（Ⅱ类医疗器械）；第二类医疗器械生产；医用口罩生产；卫生用品和一次性使用医疗用品生产；医护人员防护用品生产（Ⅰ类医疗器械）；第一类医疗器械生产；日用口罩（非医用）生产；第二类医疗器械销售；第一类医疗器械销售；医用口罩零售；日用口罩（非医用）销售；卫生用品和一次性使用医疗用品销售（依法须经批准的项目，经相关部门批准后方可开展经营活动）\n许可项目：第二类增值电信业务；发电业务、输电业务、供（配）电业务（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）\n一般项目：太阳能发电技术服务（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）"
