    "company": "浙江森马服饰股份有限公司",
    "registerStatus": "存续",
    "boss": "邱坚强",
    "registerCapital": "269409.016万元",
    "createTime": "2002-02-05",
    "address": "温州市瓯海区娄桥工业园南汇路98号",
    "province": "",
    "city": "温州市",
