    "usefulPhone": "",
    "morePhone": "0577-88098617;0577-88098622;0577-88089999;021-67288111;021-67288431;0577-85789999",
    "email": "semir@semir.com;ir@semir.com",
    "companyType": "",
    "people": "",
    "scale": "L(大型)",
    "profile": "浙江森马服饰股份有限公司是一家以虚拟经营为特色、以系列成人休闲服和儿童服饰为主导产品的品牌服饰企业。连续12年被评为中国服装行业销售、利润双百强，中国民营企业500强，位居中国服装行业竞争力10强，是中国服装行业优势企业之一。公司旗下目前拥有“森马”和“巴拉巴拉”两大服饰品牌，其中，“森马”品牌创立于1996年，产品及品牌定位于年轻、时尚、活力、高性价比的大众休闲服饰，主要面向16～30岁的青少年学生群体以及刚踏入社会的年轻群体。“巴拉巴拉”品牌创立于2002年，定位为专业、时尚童装，主要面向0~14岁中产阶级及小康家庭的童装消费群体。该品牌曾荣获中国服装品牌潜力大奖、中国十大童装品牌。“巴拉巴拉”品牌的市场占有率和品牌知名度都居国内童装品牌前列，被誉为“创造了中国童装品牌的发展奇迹”。自企业创办以来，森马服饰就采用了虚拟经营模式并在实践中不断加以创新，将服装生产外包，专注于产品设计、品牌传播、供应链管理及渠道拓展，“长板做长，短板外包”。在20年的发展中，森马服饰以“整合创新，共赢发展”为经营思路，着力扮演好“渠道规划者、资源整合者、品牌管理者、人文力行者”四种角色，立足服装实业，立足国内市场，立足品牌建设，立足人文引领，以国际化视野整合全球优势资源，以专注的心态和执著的精神做实业，走出了一条社会化大生产、专业化分工协作的路子。从企业创办之初，森马服饰就确立了“小河有水大河满”的经营哲学，强调与合作伙伴等利益相关方的共赢，追求企业与员工、企业与社会之间的和谐发展。2011年3月，森马服饰在深交所中小板成功上市，成为市值服饰类上市公司。在消费升级的时代大背景下，森马怀着“引领品质时尚，创享幸福生活”的新使命，通过构建服装产业、儿童产业、电商产业和新兴产业四大产业集群，全力打造全员创业、资本运营、产业孵化、多品牌繁荣和开放共赢的森马大平台，力争在新的五年，实现终端销售800亿、创市值千亿、创税利100亿、再造10个创业合伙人平台、再造10个创业品牌、培育2-3家上市企业的宏伟目标，致力于成为具有全球影响力的时尚服务提供商。",
    "businessScope": "一般项目：服装服饰零售；服装服饰批发；鞋帽零售；鞋帽批发；针纺织品销售；针纺织品及原料销售；箱包销售；玩具、动漫及游艺用品销售；母婴用品销售；眼镜销售（不含隐形眼镜）；日用品销售；工艺美术品及收藏品零售（象牙及其制品除外）；工艺美术品及收藏品批发（象牙及其制品除外）；文具用品零售；文具用品批发；厨具卫具及日用杂品批发；卫生用品和一次性使用医疗用品销售；塑料制品销售；橡胶制品销售；服装制造；服饰制造；皮革制品制造；羽毛（绒）及制品制造；鞋制造；箱包制造；专业设计服务；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；灯具销售；日用百货销售；家用视听设备销售；化妆品零售；化妆品批发；劳动保护用品生产；劳动保护用品销售；特种劳动防护用品生产；特种劳动防护用品销售；非居住房地产租赁；普通货物仓储服务（不含危险化学品等需许可审批的项目）；会议及展览服务；图文设计制作；物业管理；货物进出口；个人卫生用品销售；日用口罩（非医用）销售；图书出租；期刊出租；社会经济咨询服务；个人商务服务；知识产权服务（专利代理服务除外）（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：住宅室内装饰装修；出版物零售（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）。"
