    "profile": "海澜之家集团股份有限公司成立于1997年，是一家主要从事品牌管理、供应链管理、营销网络管理的大型消费品牌运营平台公司。截至报告期末，公司旗下拥有包括男装、女装、童装、职业装及生活家居等品牌，主要品牌及产品的具体情况如下:1、海澜之家(HLA),海澜之家是一个国际化一站式男装零售品牌，于2002年创立，为公司旗下主要品牌，致力于为20-45岁的男性提供时尚的设计和优质的产品，产品划分为商务、时尚、休闲三个系列，主要包括T恤、衬衫、裤子、西装、茄克衫等类别，丰富的商品能够满足男性在着装方面的几乎全部需求。海澜之家品牌定位快速消费品、生活必需品，倡导“高品位、中价位”的营销理念，以优质的产品、丰富的款式、大众的价格、贴心的服务迅速占领市场,“海澜之家——男人的衣柜”,已经被大众消费群所追捧。2、圣凯诺(SANCANAL),圣凯诺创立于上世纪90年代，定位于职业装团体定制，采用传统的自主生产经营模式为金融、电力、电信、邮政、政府机构及其他企事业单位提供量身定制的商务职业装，产品涵盖了男女式西服、西裤、马甲、裙子、衬衫、茄克、大衣、风衣等全品类服饰，尤其以“精品西服”、“精品免烫衬衫”、“成衣免烫衬衫”等为代表的拳头产品，广受客户欢迎。二十余年来，圣凯诺始终专注于团体定制的品质与荣耀，兼容并蓄了诸多国际品牌的设计神韵，在意大利版型风格的基础上，结合国人体型特点进行了重新设计，秉承简洁雅致、内涵稳重的风格，以精良严谨的制作工艺，淬炼出圣凯诺独特的产品价值。3、海澜优选生活馆(HEILANHOME),海澜优选生活馆是公司旗下的全新生活方式类家居品牌，专注国民优质生活精选的一站式家居产品集合店，为消费者提供涵盖办公用品、化妆用品、餐桌用品、厨房用品、床上用品、护理用品、旅行用品、生活用品、服装类和家具用品十大优选商品系列产品。海澜优选生活馆拥有近4000种的商品种类，遍及服装、生活杂货以及时尚家居三大领域，旨在将高品质兼具高性价比的美学装置渗透到现代人日常生活所需的方方面面。海澜优选生活馆依靠海澜之家强大的供应链管理优势和超过十五年丰富的零售管理经验，让“优选优价”这个消费者理应享受的权益，成为可以呈现给消费者的实在利益。4、OVV,OVV品牌创立于2017年，以职场女性生活场景为设计出发点，用天然优质面料、考究的立体剪裁工艺、简约风格设计为现代都市女性提供不费力、高性价比的高级成衣，打破沉闷的职场穿着。OVV产品分为NEWCLASSIC新经典系列、SMARTCASUAL精致休闲系列、VACATION&EVENT度假派对系列三大系列。OVV严选羊绒、纯羊毛精纺、真丝等优质面料，配合剪裁与设计，从时尚潮流中借鉴趣味的元素，让每件单品都成为当季的用心之作。5、黑鲸(HLAJEANS),黑鲸是公司旗下专为都市新青年打造的快时尚男女装品牌，创立于2017年。秉承公司的服装全品类研发设计与供应链管理能力，黑鲸能够为都市青年提供兼具设计感与性价比的时尚服饰产品，涵盖运动、街头、联名等系列的多元商品。年轻人对于服饰追求品质也期待性价比，追求百搭也期待设计感。针对年轻人的消费痛点，黑鲸提出“我不是基本款，件件都有料”的产品定位。面向18-35岁的泛90后城市新青年，给他们提供设计感与性价比完美平衡的超出期待的服装穿着体验。黑鲸作为充满趣味性与创意灵感的年轻品牌，乐于与年轻人热衷的艺术、动漫、综艺、电竞等展开合作，与年轻人一起共创潮流生活方式。6、男生女生(HEYLADS),男生女生是公司于2018年通过对其增资实现控股的童装品牌，目标群体为6个月至16岁的孩子，定位高品质高性价比，倡导“买得起的时尚、超值的产品”,打造一站式全品类儿童时尚、休闲服饰品牌。产品风格主要有棉麻、时尚休闲、经典校园风、韩风淑女、户外运动等十二大系列，涵盖了服饰、鞋子、家居服、帽子、书包、袜子、内裤、围巾、手套、头饰等全品类的产品。7、英氏(YEEHOO),英氏是公司2017年入股，并于2019年实现控股的童装品牌。旗下自有品牌“YeeHoo英氏”自1995年创立以来，始终专注0-3岁婴幼儿生活必用品，并延伸至6岁成长所需。定位高端高品质，秉承“纯、柔、净、美”的产品哲学，产品线主要覆盖婴童内衣、外出服、童床、床品、车椅、鞋帽袜、洗护等全品类，为中国家庭及孩子享受高品质生活方式提供衣、食、住、行、伴等方面的解决方案。公司凭借“平台+品牌”的经营模式，通过打造产业链战略联盟、构筑优质的营销网络，让每一位消费者尽享物超所值的产品和服务;通过对加盟店的类直营管理，实现门店统一管理和快速扩张;通过以共赢的理念整合服装产业链资源，带动整个产业链经营的良性循环，产业链各方承担有限风险，有效化解经营风险。目前公司已形成独具特色与竞争优势的品牌连锁运营管理模式，为公司长期稳定的发展奠定了坚实的基础。2019年，公司实现营业收入219.70亿元，归属于上市公司股东的净利润32.11亿元。截止报告期末，海澜之家是沪深300指数、MSCI中国A股在岸指数成分股、沪股通标的股、央视财经50系列指数样本股。截止2019年12月末，公司门店总数7,254家，其中海澜之家系列品牌5,598家，其他品牌1,656家。",
    "businessScope": "毛纺新技术、新产品、新材料、通讯产品的研发、销售，环保高新技术产品的开发及投资，精纺呢绒、毛纱、服装（包含执法服、制服）、针织品、衬衫、领带、袜子、纺织原料、服饰、皮革、毛皮、羽毛及其制品、鞋子、服装辅料、防静电工作服、阻燃工作服、防酸工作服的制造、加工、销售，安全帽、塑料橡胶帽的销售，自营和代理各类商品及技术的进出口业务；自有房屋的租赁服务；物业管理（凭有效资质证书经营）；服装设计。（依法须经批准的项目，经相关部门批准后方可开展经营活动）\n一般项目：互联网销售（除销售需要许可的商品）；品牌管理；企业管理咨询；专业设计服务；信息系统运行维护服务；信息系统集成服务；软件开发；信息技术咨询服务；互联网数据服务；数据处理和存储支持服务；软件销售；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；会议及展览服务；以自有资金从事投资活动；股权投资；日用百货销售；户外用品销售；办公用品销售；文具用品零售；母婴用品销售；家用电器销售；体育用品及器材零售；化妆品零售；五金产品零售；第一类医疗器械销售；服饰研发；服装、服饰检验、整理服务；大数据服务；计算机系统服务；企业管理；供应链管理服务（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）"
