    "profile": "华纺股份有限公司坐落于山东半岛蓝色经济区和环渤海经济圈交汇的黄河三角洲腹地——滨州，至今拥有43年沿革历史，2001年9月在上交所挂牌上市（股票代码：600448），是中国纺织印染行业的龙头骨干企业，资产总额超过35亿元。作为中国“高品质纺织品缔造者、健康时尚生活倡导者”，创造性开启“一体两翼”的发展战略布局，产业领域涉及纺织、印染、家纺成品、服装、热电、房地产及金融和信息服务等。主要产业项目年产能分别为：印染布4.5亿米，花色品种达10000余个；现有环锭纺4万锭、紧密纺2.8万锭；床品类产品2070万件（套）；服装300万件，产品出口比重达85%以上。公司具有综合竞争优势，全力推进“智慧华纺”建设，在产品开发、技术创新、质量提升、节能减排、市场开拓、品牌运营和企业文化建设等方面协同推进，拥有国家认定企业技术中心、纺织工业（山东）纺织品检测中心，建有工程技术研究院、博士后工作站、“智慧纺织”实验室、华纺HFCPS中心，是“中国印染产品开发基地”、“山东省印染节能减排工程技术研究中心”和中国质量检验协会确认的“打假扶优重点保护企业”。公司全面推行卓越绩效和精益生产管理，先后通过ISO9001：2008质量体系、ISO14001：1996环境管理体系、OHSAS18001:1999(GB/T28001-2001)职业健康安全管理体系、能源管理体系和知识产权管理体系认证，产品获得Oeko-Tex Standard 100国际环保纺织品认证和“白名单资质证书”，多项技术成果获得国家、省部及市级科技进步奖，“棉冷轧堆染色关键技术的应用及产业化”成果获得“国家科技进步二等奖”；是公安部和中国人民解放军总后勤部指定“专用面料生产企业”。拥有自身品牌运营团队、设计研发团队和生产销售团队，公司品牌商标已在中国、美国、欧盟、中国香港等国家和地区注册成功，被山东省名牌战略推进委员会、山东省质量技术监督局授予“山东名牌”称号。公司以“上善若水、厚德载物”为理念，把打造“家文化”作为企业文化建设主题，技术委员会、设备委员会、能源委员会、安全委员会、轮班联合会、职工读书会等组织，成为传导“家文化”的纽带，敬业、责任、担当、感恩、成长是“家文化”的主题词。公司积极践行社会责任，先后向汶川、玉树、鲁甸等地震灾区和国家慈善组织捐款逾千万元；“领航时代”志愿者团队每年向社会提供志愿服务5000多小时；近千名员工成为捐献造血干细胞志愿者，加入“中华骨髓库”。公司成立了以普通女工命名的“刘海霞爱心工作室”，先后多次救助四川、西藏等地贫困儿童，走进滨州特殊教育学校、社会福利院献爱心，经验被山东省轻纺烟草工会在系统内进行重点介绍。公司先后由中国建设银行山东分行授予“AAA级信用企业”，中国海关认定为“海关AA类管理企业资格”，山东省工商局授予“省级重合同、守信用企业”，山东省总工会授予“富民兴鲁劳动奖状”、“山东省劳动关系和谐企业”，中国纺织工业联合会、全国轻纺烟草工会联合授予“中国纺织行业劳动关系和谐企业”。公司以对社会、对国家、对股东、对员工、对企业、对全民、对环境等多方面的负责态度，于2013年8月18日在北京人民大会堂发布了自身的社会责任报告，并被中国纺织工业联合会授予“中国纺织服装行业社会责任信息披露实践示范奖”；连续多年跻身“中国印染行业十佳企业”。2013年，公司以整体发展的卓群表现，被中华全国总工会授予“全国五一劳动奖状”称号，2015年获得“全国五一巾帼标兵岗”称号。",
    "businessScope": "许可项目：热力生产和供应；发电业务、输电业务、供（配）电业务；第二类医疗器械生产；第三类医疗器械生产；第三类医疗器械经营；道路货物运输（不含危险货物）。（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以相关部门批准文件或许可证件为准）一般项目：棉花收购；棉花加工；纺纱加工；面料纺织加工；面料印染加工；合成纤维制造；家用纺织制成品制造；服装制造；服饰制造；服装辅料制造；产业用纺织制成品制造；家居用品制造；箱包制造；塑料制品制造；涂料制造（不含危险化学品）；染料制造；工艺美术品及礼仪用品制造（象牙及其制品除外）；劳动保护用品生产；特种劳动防护用品生产；日用口罩（非医用）生产；化工产品生产（不含许可类化工产品）；第一类医疗器械生产；再生资源加工；机械电气设备制造；建筑砌块制造；棉、麻销售；针纺织品及原料销售；家居用品销售；服装辅料销售；合成纤维销售；服装服饰批发；服装服饰零售；产业用纺织制成品销售；箱包销售；金属制品销售；塑料制品销售；包装材料及制品销售；建筑装饰材料销售；化工产品销售（不含许可类化工产品）；涂料销售（不含危险化学品）；工艺美术品及礼仪用品销售（象牙及其制品除外）；劳动保护用品销售；特种劳动防护用品销售；第一类医疗器械销售；第二类医疗器械销售；日用口罩（非医用）销售；染料销售；体育用品及器材零售；五金产品零售；日用品销售；电子产品销售；办公用品销售；互联网销售（除销售需要许可的商品）；机械设备租赁；小微型客车租赁经营服务；软件开发；技术服务、技术开发、技术咨询、技术交流、技术转让、技术推广；机械电气设备销售；建筑砌块销售；普通货物仓储服务（不含危险化学品等需许可审批的项目）；货物进出口；进出口代理；再生资源回收（除生产性废旧金属）；再生资源销售；户外用品销售；摄影扩印服务；摄像及视频制作服务；资源再生利用技术研发；新材料技术研发；洗染服务；洗烫服务；仓储设备租赁服务。（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）"
