    "profile": "江苏红豆实业股份有限公司成立于1995年6月，是红豆集团(江苏省重点企业集团，国务院深化改革试点企业)核心子公司,2001年1月8日在上海证券交易所挂牌上市，股票代码600400。公司以品牌运营及服装制造为优势，形成红豆男装全域零售、红豆职业装定制两大主营业务。红豆男装全域零售业务，以“男装更舒适，穿红豆”为品牌定位，专注打造舒适男装专家，为中高端男性消费者提供商务正装、休闲、运动等风格的优质时尚服饰产品，满足其在不同场合的一站式着装需求。目前，全域零售的线下销售渠道主要为全国二三线城市，同时依托门店数字化建设增强用户互动体验;线上销售由公司直营，主要入驻天猫、京东、唯品会、苏宁、小程序商城等第三方主流电商开放平台，多触点触达用户。红豆职业装定制业务，主要为客户量身定制各类中高档职业装，以及个性化的轻定制服务，客户范围覆盖金融、通信、交通运输等行业。公司一直致力于民族品牌建设，不断坚持创新变革。品牌自创建以来，坚持以打造国内顶尖文化品牌为己任，从产品、服务、传播等多维度构建以“情”文化为核心的品牌体系。2019年10月,“红豆”入选央视大国品牌“新中国成立70周年70品牌”;2021年6月，世界品牌实验室公布中国500最具价值品牌排行榜,“红豆”跃居“品牌500强”第79位。新零售时代，红豆股份将持续坚持重点发展红豆男装零售业务，加速实施智慧化建设，推动公司向“智慧创造运营”经营模式转型的发展战略，致力于成为男装行业领军型企业。智能制造公司以智能制造助力产品升级，通过自动化、数字化、信息化、可视化建设实现设备智能化、系统智能化、管理智能化，全力打造智能化车间，提供全方位的定制化产品设计、生产、配送及售后等系列配套服务，为用户提供更优质的产品体验和更贴心的服务体验。公司目前已实现了全渠道营销，建立了覆盖线下门店和线上各平台的全渠道营销网络体系，多触点触达客户，消费者下单一分钟以内就能快速匹配发货地;打通线上线下全渠道会员，通过对会员标签、会员行为等分析实现精准化营销。并重点推进企业微信、超级导购系统提升运营能力，同时结合快手、抖音、一直播、网红直播带货等形式拓宽销售渠道。",
    "businessScope": "许可项目：第二类医疗器械生产；医用口罩生产；自来水生产与供应；货物进出口；技术进出口；进出口代理（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）一般项目：服装制造；服饰制造；服装服饰零售；服装服饰批发；鞋帽零售；鞋帽批发；箱包销售；皮革制品销售；互联网销售（除销售需要许可的商品）；劳动保护用品生产；劳动保护用品销售；特种劳动防护用品生产；特种劳动防护用品销售；第一类医疗器械生产；第一类医疗器械销售；第二类医疗器械销售；医用口罩零售；日用口罩（非医用）生产；日用口罩（非医用）销售；产业用纺织制成品生产；产业用纺织制成品销售；家用纺织制成品制造；针纺织品销售；专业设计服务；日用品销售；日用百货销售；塑料制品销售；金属制品销售；橡胶制品销售；纸制品销售；照明器具销售；家具销售；家用电器销售；工艺美术品及礼仪用品销售（象牙及其制品除外）；电子产品销售；货币专用设备销售；电气信号设备装置销售；可穿戴智能设备销售；品牌管理；企业管理咨询；非居住房地产租赁（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）"
