    "profile": "坦博尔企业简介一、企业概况青州坦博尔服饰有限公司是一家集设计、生产、销售于一体的现代化羽绒服装企业。企业在创立之初就确立了“以创新求发展，以质量创品牌”的企业理念和让老百姓真正得实惠的经营宗旨。坦博尔人视质量为生命。为此，公司引进了具有国际先进水平的设计、生产、检测流水线，并从全国各地广招人才，确保产品质量和企业稳健、持续发展。先进的设施、设备，一流的人才保证了企业强劲的研发、生产能力。2005年9月，坦博尔羽绒服被国家质检总局评为“中国名牌产品”，实现了我市中国名牌“零”的突破。2010年10月8日，坦博尔被国家工商总局行政认定为“中国驰名商标”，实现了公司品牌战略发展历程中新的跨越。公司先后参加了中国名牌产品推进成果展、中国（北京）国际服装服饰博览会、山东品牌万里行、山东省鲁台经贸洽谈会和青岛国际时装周等展览发布活动。每到一处，坦博尔展台和专场发布会都成为一道靓丽的风景，成为各方关注的焦点。几年来，坦博尔羽绒服以独特的艺术视角、灵性的色彩运用、简约细致的艺术风格，为羽绒服装业增添了时尚元素，得到了广大消费者的信赖和业内好评，市场销售区域不断扩大。目前产品已销往北京、上海、河北、河南、东北叁省、山西、天津、安徽、湖北、江苏等省市，单品牌市场综合占有率居行业前列。",
