    "profile": "EP雅莹：塑造代表中国的亲奢时尚品牌EP雅莹隶属于华之毅时尚集团，以亲民奢侈的品牌定位、精湛工艺成为中国时装的领导品牌。“外在优雅动人，内在晶莹如玉”，EP雅莹代表了新中国的时尚美学，包括对中国传统文化的吸收、提炼和现代文化的融合，代表了对东方和西方的潮流趋势与艺术的融合，引领时尚、优雅的精致生活方式，传递平衡。爱。幸福的价值理念。EP雅莹提供优雅、时尚、高品质的全系列服装，满足都市女性多重生活形态的着装需求。旗下包括ELEGANT PROSPER、EP和EP HOLIDAY三大产品线：ELEGANT PROSPER围绕中国高端女性生活形态及需求，展示中国式的臻品生活质感，追求最高标准的中国设计美学、材质及工艺，演绎极致的高端品味生活。EP 针对中国富裕阶层女性的高端精品生活而设计，满足她们在工作与生活中的着装需求，用经典的设计语言结合更多的潮流元素，引领中国女性的高端精品时尚生活方式。EP HOLIDAY针对中国富裕阶层女性的高端休闲文化生活而设计，满足她们在假日中的着装需求，结合时尚度及舒适度，引导现代中国女性的高端假日休闲时尚生活方式。EP雅莹现有优质终端门店约400家，主要分布于一线及省会城市，形成了EP雅莹之家、时尚生活馆、购物中心店、百货店、专卖店、机场店和网络商城组成的全方位、立体化的营销网络。2010年8月，EP雅莹进驻中国澳门，正式开始了品牌输出，开始了海外市场的开拓之路。2013年12月全新概念的北京华贸EP雅莹之家华彩启幕，临街独栋的四层建筑，近2000平米的超大空间，成为感受EP雅莹时尚之美、艺术之美与生活之美的体验之境。2014年10月，杭州万象城EP雅莹之家启幕，这是EP雅莹家文化的延展，是江南园林与当代时尚的结合，是多元化的融汇。秀美精致的艺术空间为顾客打造最尊贵的服务。2014年2月27日，2015年意大利米兰世博会中国馆新闻发布会在北京召开，EP雅莹成为“2015年意大利米兰世博会中国馆的全球合作伙伴”。作为代表中国最美的时装品牌，EP雅莹将与中国馆一起走向时尚之都米兰，向世界展示东方时尚之美。",
    "businessScope": "一般项目：服装制造；服饰制造；钟表与计时仪器制造；眼镜制造；箱包制造；家用纺织制成品制造；绣花加工；服装辅料制造；服装服饰零售；服装服饰批发；鞋帽零售；羽毛（绒）及制品销售；化妆品零售；钟表与计时仪器销售；眼镜销售（不含隐形眼镜）；箱包销售；服装辅料销售；皮革制品销售；针纺织品销售；针纺织品及原料销售；金银制品销售；珠宝首饰零售；珠宝首饰批发；工艺美术品及收藏品零售（象牙及其制品除外）；工艺美术品及礼仪用品销售（象牙及其制品除外）；家居用品销售；家具销售；家用电器销售；电子产品销售；音响设备销售；日用化学产品销售；日用百货销售；日用品销售；日用杂品销售；日用口罩（非医用）销售；医用口罩零售；医用口罩批发；个人卫生用品销售；日用玻璃制品销售；传统香料制品经营；文具用品零售；户外用品销售；体育用品及器材零售；礼品花卉销售；玩具销售；玩具、动漫及游艺用品销售；专业设计服务；洗烫服务；以自有资金从事投资活动；自有资金投资的资产管理服务；非居住房地产租赁；软件开发；人工智能应用软件开发；货物进出口；技术进出口（除依法须经批准的项目外，凭营业执照依法自主开展经营活动）。许可项目：食品销售（依法须经批准的项目，经相关部门批准后方可开展经营活动，具体经营项目以审批结果为准）。"
